#!/usr/bin/env node
import {
  checkFiles
} from "./chunk-GLH7CMPL.js";
import {
  resolveStockFromConfig
} from "./chunk-EXIXW6Q5.js";
import {
  resolveGlob
} from "./chunk-SH5HYKQV.js";
import "./chunk-XW73TKNN.js";
import "./chunk-4MSISIPG.js";
import {
  renderCheckResult,
  reportRejectedIngredients
} from "./chunk-4A6RJKSG.js";
import {
  loadDbSafe
} from "./chunk-J5CTY35W.js";
import {
  loadConfig
} from "./chunk-LYQHWV53.js";
import "./chunk-IWNALT6P.js";
import "./chunk-5APUWLPI.js";
import {
  ExitCode,
  GramCLIError
} from "./chunk-IXNX2GX7.js";

// src/commands/check.ts
import { defineCommand } from "citty";
import { spinner, log } from "@clack/prompts";
var check_default = defineCommand({
  meta: {
    name: "check",
    description: "Validate .gram recipe files for syntax, structure, and ingredient database completeness"
  },
  args: {
    pattern: {
      type: "positional",
      description: "File path or glob pattern (default: **/*.gram)",
      required: false
    },
    db: {
      type: "string",
      description: "Path to ingredient database YAML"
    },
    "skip-db": {
      type: "boolean",
      description: "Skip ingredient database enrichment",
      default: false
    },
    strict: {
      type: "boolean",
      description: "Treat every warning as an error (e.g. for CI)",
      default: false
    },
    stock: {
      type: "string",
      description: "Comma-separated @use specifiers already on hand for this check (e.g. @bases/pate.gram,./levain.gram)"
    }
  },
  async run({ args }) {
    const patterns = args._.length > 0 ? args._ : ["**/*.gram"];
    let files = [];
    try {
      files = await resolveGlob(patterns);
    } catch (err) {
      if (err instanceof GramCLIError) {
        log.error(err.message);
        process.exit(err.exitCode);
      }
      throw err;
    }
    const config = await loadConfig();
    const dbResult = args["skip-db"] ? null : await loadDbSafe(config, args.db);
    if (dbResult) reportRejectedIngredients(dbResult.rejected, dbResult.dbPath);
    const db = dbResult?.data ?? null;
    const stock = resolveStockFromConfig(args.stock, config);
    const n = files.length;
    const s = spinner();
    s.start(`Checking ${n} file${n !== 1 ? "s" : ""}\u2026`);
    const result = await checkFiles(files, {
      db: db ?? void 0,
      strict: args.strict,
      paths: config.paths,
      stock
    });
    s.stop(`Checked ${n} file${n !== 1 ? "s" : ""}.`);
    renderCheckResult(result);
    if (result.hasErrors) {
      process.exit(ExitCode.Error);
    }
  }
});
export {
  check_default as default
};
